values ('ap_chemistry', 9, '9.3', array['9.3', '9.6']::text[], 'formula', 'Gibbs free energy equation', '\Delta G^{\circ}=\Delta H^{\circ}-T\Delta S^{\circ}', '[]'::jsonb, NULL, 'When explaining favorability, state which term (enthalpy or entropy) actually has the sign supporting ΔG° < 0; do not claim both contribute favorably unless both do.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-007; ced=9.3.A.5 EQN: ΔG° = ΔH° − T ΔS°')
