insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.3', array['9.3']::text[], 'list_sequence', 'Signs of ΔH° and ΔS° and temperatures favoring ΔG° < 0', 'The signs of ΔH° and ΔS° predict the temperatures at which a process is thermodynamically favored.', '[{"label": "ΔH° < 0, ΔS° > 0", "meaning": "Favored at all T; no calculation needed to show ΔG° < 0"}, {"label": "ΔH° > 0, ΔS° < 0", "meaning": "Favored at no T; no calculation needed to show ΔG° > 0"}, {"label": "ΔH° > 0, ΔS° > 0", "meaning": "Favored at high T"}, {"label": "ΔH° < 0, ΔS° < 0", "meaning": "Favored at low T"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-008; ced=9.3.A.6 "temperature conditions for a process to be thermodynamically favored (ΔG° < 0) can be predicted from the signs of ΔH° and ΔS°"')
