insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.3', array['9.3', '9.5']::text[], 'vocabulary', 'Standard state (for ΔG°)', 'ΔG° applies when all reactants and products are in a standard state: pure substances, solutions of 1.0 M concentration, or gases at 1.0 atm (or 1.0 bar).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-005; ced=9.3.A.1 "as pure substances, as solutions of 1.0 M concentration, or as gases at a pressure of 1.0 atm (or 1.0 bar)"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.3', array['9.3', '9.5', '9.9']::text[], 'vocabulary', 'Thermodynamically favored', 'A process is thermodynamically favored when its standard Gibbs free energy change is negative (ΔG° < 0); this term is preferred over ''spontaneous'', which is often misread as ''suddenly'' or ''without cause''.', '[]'::jsonb, NULL, 'Use ''thermodynamically favored'' rather than ''spontaneous''; favored does not mean fast.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-004; ced=9.3.A.2 "When ΔGo < 0 for the process, it is said to be thermodynamically favored."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.3', array['9.3']::text[], 'formula', 'ΔG° from standard free energies of formation', '\Delta G^{\circ}_{reaction}=\Sigma\Delta G_f^{\circ}{}_{products}-\Sigma\Delta G_f^{\circ}{}_{reactants}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-006; ced=9.3.A.3 EQN: ΔG°reaction = ΣΔGf°products − ΣΔGf°reactants')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.4', array['9.4']::text[], 'vocabulary', 'Kinetic control', 'A process that is thermodynamically favored but does not proceed at a measurable rate is under kinetic control, commonly because of high activation energy.', '[]'::jsonb, NULL, 'A lack of observable reaction does not mean the system is at equilibrium.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-009; ced=9.4.A.2 "Processes that are thermodynamically favored, but do not proceed at a measurable rate, are under ''kinetic control.''"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.5', array['9.5']::text[], 'formula', 'Equilibrium constant from ΔG°', 'K=e^{-\Delta G^{\circ}/RT}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-010; ced=9.5.A.2 EQN: K = e^(−ΔG°/RT)')
