insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.5', array['9.5']::text[], 'convention', 'Sign of ΔG° and size of K', 'ΔG° < 0 means K > 1 (products favored at equilibrium); ΔG° > 0 means K < 1 (reactants favored); ΔG° near zero means K is close to 1, and K deviates strongly from 1 when |ΔG°| is much larger than RT.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-012; ced=9.5.A.3-4 "Processes with ΔG° < 0 favor products (i.e., K > 1)"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.5', array['9.5']::text[], 'formula', 'ΔG° from the equilibrium constant', '\Delta G^{\circ}=-RT\ln K', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-011; ced=9.5.A.2 EQN: ΔG° = −RT ln K')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.6', array['9.6']::text[], 'list_sequence', 'Factors in the free energy of dissolution', 'ΔG° of dissolution reflects three factors, each with enthalpic and entropic contributions whose signs and relative magnitudes can be estimated; the total is hard to predict because they largely cancel.', '[{"label": "1", "meaning": "Breaking the intermolecular interactions that hold the solid together"}, {"label": "2", "meaning": "Reorganization of the solvent around the dissolved species"}, {"label": "3", "meaning": "Interaction of the dissolved species with the solvent"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-013; ced=9.6.A.1 "the breaking of the intermolecular interactions that hold the solid together, the reorganization of the solvent..."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.7', array['9.7']::text[], 'convention', 'Coupled reactions', 'An unfavorable reaction that makes a desired product is coupled to a favorable reaction (e.g., ATP to ADP) through one or more shared common intermediates, and the summed overall reaction has ΔG° < 0.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-015; ced=9.7.A.2 "the individual reactions share one or more common intermediates"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.7', array['9.7', '9.8']::text[], 'convention', 'Driving an unfavorable process with external energy', 'An external energy source (electrical energy for an electrolytic cell or battery charging, light for photosynthesis) can make a thermodynamically unfavorable process occur.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-014; ced=9.7.A.1 "An external source of energy can be used to make a thermodynamically unfavorable process occur."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.8', array['9.8', '9.10']::text[], 'diagram', 'Electrochemical cell diagram', 'Cell diagrams are read to identify where each half-reaction occurs, the direction of current and electron flow, and the cell type; each component has a specific role.', '[{"label": "Electrodes", "meaning": "Anode (oxidation) and cathode (reduction); mass change or gas evolution can occur at an electrode"}, {"label": "Half-cell solutions", "meaning": "Contain the active species of each half-reaction"}, {"label": "Salt bridge", "meaning": "Allows ion flow between half-cells"}, {"label": "Voltage/current measuring device", "meaning": "Measures cell potential or current"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-018; ced=9.8.A.1 "electrodes, solutions in the half-cells, salt bridge, voltage/current measuring device"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.8', array['9.8', '9.9']::text[], 'convention', 'Galvanic vs. electrolytic cells', 'Galvanic (voltaic) cells involve a thermodynamically favored reaction, whereas electrolytic cells involve a thermodynamically unfavored reaction that needs an applied potential.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-017; ced=9.8.A.2 "Galvanic, sometimes called voltaic, cells involve a thermodynamically favored reaction, whereas electrolytic cells involve a thermodynamically unfavored reaction."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.8', array['9.8', '9.9', '9.11']::text[], 'convention', 'Oxidation at the anode, reduction at the cathode', 'In all electrochemical cells, galvanic and electrolytic, oxidation occurs at the anode and reduction occurs at the cathode.', '[]'::jsonb, NULL, 'Do not assume the anode/cathode role from an earlier part of a question carries over; reassign it from which half-reaction is oxidation and which is reduction in each new cell.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-016; ced=9.8.A.3 "oxidation occurs at the anode and reduction occurs at the cathode"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
