insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.9', array['9.9']::text[], 'formula', 'Free energy and standard cell potential', '\Delta G^{\circ}=-nFE^{\circ}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-020; ced=9.9.A.3 EQN: ΔGo = −nFEo')
