insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.9', array['9.9']::text[], 'convention', 'Standard cell potential from half-reactions', 'Identify the oxidation and reduction half-reactions and use their standard reduction potentials to calculate the standard cell potential E°; a positive E° means the reaction is thermodynamically favored and a negative E° means it is unfavored.', '[]'::jsonb, NULL, 'To find the maximum cell potential, pick the pairing in which the oxidation and reduction roles give the largest positive E°; a metal''s role can change from one part of a question to the next.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-019; ced=9.9.A.2 "identifying the oxidation and reduction half-reactions and their respective standard reduction potentials"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.10', array['9.10']::text[], 'convention', 'Cell potential and distance from equilibrium', 'Standard conditions have Q = 1; moving farther from equilibrium than Q = 1 increases |E| relative to E°, moving closer decreases it, and E = 0 at equilibrium (Q = K).', '[]'::jsonb, NULL, 'Le Châtelier''s principle does not apply to electrochemical cells because they are not at equilibrium; justify with distance from equilibrium and Q versus K instead.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-022; ced=9.10.A.3 "reaching zero at equilibrium (when Q = K)"; 9.10.A.2')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 9, '9.10', array['9.10']::text[], 'formula', 'Nernst equation (qualitative use)', 'E=E^{\circ}-\frac{RT}{nF}\ln Q', '[]'::jsonb, NULL, 'A bare numeric Nernst calculation is not enough; add a qualitative justification of how concentration or Q changes the cell potential relative to E°.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u9-r1-021; ced=9.10.A.4 "the qualitative use of the Nernst equation: E = Eo − (RT/nF) ln Q"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
